//! ECS Example - Demonstrating Litt Engine ECS usage\n\nuse litt_ecs::*;\nuse litt_math::*;\n\n// =============================================================================\n// Component Definitions\n// =============================================================================\n\n/// Transform component - position, rotation, scale\n#[derive(Clone, Debug, Default)]\npub struct Transform {\n    pub position: Vec3,\n    pub rotation: f32,\n    pub scale: Vec3,\n}\n\n/// Velocity component\n#[derive(Clone, Debug, Default)]\npub struct Velocity {\n    pub linear: Vec3,\n    pub angular: f32,\n}\n\n/// Mesh component\n#[derive(Clone, Debug, Default)]\npub struct Mesh {\n    pub vertex_count: u32,\n    pub index_count: u32,\n}\n\n/// Name component for debugging\n#[derive(Clone, Debug)]\npub struct Name {\n    pub value: String,\n}\n\n// =============================================================================\n// Systems\n// =============================================================================\n\n/// Movement system - updates positions based on velocity\npub struct MovementSystem {\n    pub dt: f32,\n}\n\nimpl System for MovementSystem {\n    fn name(&self) -> &str { "movement" }\n\n    fn update(&mut self, world: &mut World, _dt: f32) {\n        for entity in world.query_entities_with::<Transform, Velocity>() {\n            if let (Some(transform), Some(velocity)) = (\n                world.get_component::<Transform>(entity),\n                world.get_component::<Velocity>(entity),\n            ) {\n                let new_pos = transform.position + velocity.linear * self.dt;\n                world.add_component(entity, Transform {\n                    position: new_pos,\n                    ..transform.clone()\n                });\n            }\n        }\n    }\n}\n\n/// Debug system - prints entity information\npub struct DebugSystem;\n\nimpl System for DebugSystem {\n    fn name(&self) -> &str { "debug" }\n\n    fn update(&mut self, world: &mut World, _dt: f32) {\n        println!("World has {} entities", world.entity_count());\n        \n        for entity in world.query_entities::<Transform>() {\n            if let Some(transform) = world.get_component::<Transform>(entity) {\n                if let Some(name) = world.get_component::<Name>(entity) {\n                    println!("  {} at ({}, {}, {})", name.value, transform.position.0, transform.position.1, transform.position.2);\n                } else {\n                    println!("  Entity {} at ({}, {}, {})", entity, transform.position.0, transform.position.1, transform.position.2);\n                }\n            }\n        }\n    }\n}\n\n/// Cleanup system - removes entities without transforms\npub struct CleanupSystem;\n\nimpl System for CleanupSystem {\n    fn name(&self) -> &str { "cleanup" }\n\n    fn update(&mut self, world: &mut World, _dt: f32) {\n        // Remove entities that have no transform (cleanup marked for deletion)\n        // This is a simplified example - real cleanup would use a DeathComponent\n        let entities: Vec<Entity> = world.entities().collect();\n        for entity in entities {\n            if !world.has_component::<Transform>(entity) {\n                world.destroy_entity(entity);\n            }\n        }\n    }\n}\n\n// =============================================================================\n// Main\n// =============================================================================\n\nfn main() {\n    let mut world = World::new();\n\n    // Create entities with components\n    let player = world.create_entity();\n    world.add_component(player, Transform {\n        position: Vec3::new(0.0, 0.0, 0.0),\n        rotation: 0.0,\n        scale: Vec3::new(1.0, 1.0, 1.0),\n    });\n    world.add_component(player, Velocity {\n        linear: Vec3::new(1.0, 0.0, 0.0),\n        angular: 0.0,\n    });\n    world.add_component(player, Name {\n        value: "Player".to_string(),\n    });\n\n    let enemy = world.create_entity();\n    world.add_component(enemy, Transform {\n        position: Vec3::new(5.0, 0.0, 5.0),\n        rotation: 0.0,\n        scale: Vec3::new(0.5, 0.5, 0.5),\n    });\n    world.add_component(enemy, Velocity {\n        linear: Vec3::new(-1.0, 0.0, 0.0),\n        angular: 0.5,\n    });\n    world.add_component(enemy, Name {\n        value: "Enemy".to_string(),\n    });\n\n    let cube = world.create_entity();\n    world.add_component(cube, Transform {\n        position: Vec3::new(0.0, 0.5, 0.0),\n        rotation: 0.0,\n        scale: Vec3::new(1.0, 1.0, 1.0),\n    });\n    world.add_component(cube, Mesh {\n        vertex_count: 24,\n        index_count: 36,\n    });\n\n    // Setup system group\n    let mut system_group = SystemGroup::new();\n    system_group.add(MovementSystem { dt: 0.016 });\n    system_group.add(DebugSystem);\n\n    // Run game loop (simulated)\n    println!("Starting game loop...");\n    for frame in 0..5 {\n        println!("\n--- Frame {} ---", frame);\n        system_group.run(&mut world, 0.016);\n    }\n\n    println!("\nFinal entity count: {}", world.entity_count());\n}